<?phpnamespace app\api\controller\user;use app\api\controller\Controller;use app\api\model\Order as OrderModel;use think\facade\Cache;use hema\Helper;/** * 用户订单管理 */class Refund extends Controller{    private $user;    /**     * 构造方法     */    public function initialize()    {        parent::initialize();        $this->user = $this->getUserDetail();   // 用户信息    }	/**     * 订单详情     */    public function detail($order_id)    {		$order = OrderModel::detail($order_id);		Cache::set('refund_' . $order_id, $order->toArray(), 86400);//存贮24小时		return $this->renderSuccess($order);    }        /**     * 修改订单	 * $mode 参数  dec=减少 inc=增加	 * $index 产品在数组中的编号     */    public function edit($order_id,$mode,$index)    {		$refund = Cache::get('refund_' . $order_id);		if(!$refund){			return $this->renderError('订单不存在');		}		if(!isset($refund['refund_pack'])){			$refund['refund_pack'] = 0;//初始退打包费		}		if(!isset($refund['refund_express'])){			$refund['refund_express'] = 0;//初始退配送费		}		//增加操作		if($mode == 'inc'){			$refund['goods'][$index]['refund_num'] = $refund['goods'][$index]['refund_num']+1;			$refund['goods'][$index]['refund_price'] = $refund['goods'][$index]['refund_price']+$refund['goods'][$index]['goods_price'];			$refund['refund_price'] = $refund['refund_price'] + $refund['goods'][$index]['goods_price'];//计算总退款金额			//打包费退减 （外卖与自取有效）			if($refund['order_mode']['value'] != 10){				$refund['refund_pack'] = $refund['refund_pack'] + $refund['goods'][$index]['goods']['pack_price'];				$refund['refund_price'] = $refund['refund_price'] + $refund['goods'][$index]['goods']['pack_price'];			}		}else{		    if($refund['refund_price']==$refund['pay_price']){    			$refund['refund_price']=$refund['pay_price']-$refund['delivery_price']-$refund['ware_price']+$refund['activity_price'];    		}			$refund['goods'][$index]['refund_num'] = $refund['goods'][$index]['refund_num']-1;			$refund['goods'][$index]['refund_price'] = $refund['goods'][$index]['refund_price']-$refund['goods'][$index]['goods_price'];			$refund['refund_price'] = $refund['refund_price'] - $refund['goods'][$index]['goods_price'];			//打包费退减 （外卖与自取有效			if($refund['order_mode']['value'] != 10){				$refund['refund_pack'] = $refund['refund_pack'] - $refund['goods'][$index]['goods']['pack_price'];				$refund['refund_price'] = $refund['refund_price'] - $refund['goods'][$index]['goods']['pack_price'];			}			//不是全退 			$refund['refund_price'] = $refund['refund_price'] - $refund['refund_express'];		}		//如果是全部退		if($refund['refund_price']+$refund['delivery_price']+$refund['ware_price']-$refund['activity_price']>=$refund['pay_price']){			$refund['refund_price']=$refund['pay_price'];			$refund['refund_express']=$refund['delivery_price'];//退配送费		}		$refund['refund_price'] = helper::number2($refund['refund_price']);		Cache::set('refund_' . $order_id,$refund,86400);		return $this->renderSuccess($refund['refund_price']);	}	/**     * 订单退款     */    public function refund($order_id)    {		$model = OrderModel::get($order_id);		if($model->userRefund($this->request->post())){		    return $this->renderMsg('申请成功');		}		$error = $model->getError() ?: '申请失败';		return $this->renderError($error);    }}